using System;using System.IO;using System.Reflection;using System.Drawing;using System.Windows.Forms;using LoopFive;
class LanguageTests {
 static int n;static void A(bool x,string name){if(!x)throw new Exception(name);n++;Console.WriteLine("PASS "+name);}
 static object F(object o,string name){return o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(o);}
 static Control Find(Control c,string text){if(c.Text==text)return c;foreach(Control child in c.Controls){Control found=Find(child,text);if(found!=null)return found;}return null;}
 static ComboBox Selector(Control c){ComboBox b=c as ComboBox;if(b!=null&&b.Items.Count==2&&Convert.ToString(b.Items[0])=="Español"&&Convert.ToString(b.Items[1])=="English")return b;foreach(Control child in c.Controls){ComboBox found=Selector(child);if(found!=null)return found;}return null;}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string pref=Path.Combine(Storage.DataDirectory,"settings.json");byte[] backup=File.Exists(pref)?File.ReadAllBytes(pref):null;try{using(MainForm f=new MainForm()){f.Opacity=0;f.Show();Application.DoEvents();((Timer)F(f,"timer")).Stop();f.Audio.Stop();f.Engine.System.Language="es";f.ApplyLanguage();string id=f.Engine.System.KeyboardBindings[0].Action;f.Engine.Config.Name="Mi Pista · canción";f.RefreshModel();f.Engine.Import(0,new AudioClip(new float[1024],new float[1024],120,1));AudioClip clip=f.Engine.Tracks[0].Clip;TabControl tabs=(TabControl)F(f,"tabs");SettingsPage sp=(SettingsPage)F(f,"settingsPage");ComboBox selector=Selector(sp);A(selector!=null&&selector.Items.Count==2,"exactly Spanish and English are offered");selector.SelectedIndex=1;A(Language.Code=="en"&&f.Engine.System.Language=="en","language selector applies English immediately");A(Storage.LoadSystem().Language=="en","selected language persists on disk");f.Engine.Status="Sesión guardada";bool statusEnglish=true;for(int tick=0;tick<15;tick++){typeof(MainForm).GetMethod("Tick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,new object[]{null,EventArgs.Empty});statusEnglish&=((Label)F(f,"status")).Text.Contains("Session saved")&&!((Label)F(f,"status")).Text.Contains("Sesión");}A(statusEnglish,"live status remains English on every refresh");A(tabs.TabPages[0].Text=="TRACKS"&&Find(f,"OPTIONS")!=null,"navigation translated");A(Find(f,"HELP")!=null&&Find(f,"Keyboard")!=null,"header and settings translated");A(((TextBox)F(f,"sessionName")).Text=="Mi Pista · canción","user session title is preserved");A(ReferenceEquals(clip,f.Engine.Tracks[0].Clip)&&id==f.Engine.System.KeyboardBindings[0].Action,"language does not mutate audio or shortcut IDs");A(Language.T("Pista 3")=="Track 3"&&Language.T("Banco D")=="Bank D","dynamic track and bank captions translated");A(Language.T("Pista 1 · Reproducir")=="Track 1 · Play","keyboard action descriptions translated without changing IDs");TrackStrip[] strips=(TrackStrip[])F(f,"strips");for(int i=0;i<5;i++){f.Engine.Tracks[i].Config.Name="PISTA "+(i+1).ToString("00");A(strips[i].DisplayName=="TRACK "+(i+1).ToString("00"),"default track title translated in painted UI "+i);}f.Engine.Tracks[0].Config.Name="Mi Pista · canción";A(strips[0].DisplayName=="Mi Pista · canción","custom track title is never translated");f.Engine.Config.Name="Nueva sesión";f.RefreshModel();A(((TextBox)F(f,"sessionName")).Text=="New session"&&f.Engine.Config.Name=="Nueva sesión","default session title translated without mutating saved name");f.Engine.Tracks[0].Config.Name="PISTA 01";using(TrackDialog defaults=new TrackDialog(f.Engine,0,delegate{},delegate{},delegate{})){Language.Apply(defaults);A(Find(defaults,"TRACK 01") is TextBox,"default track title also translated in editor");}f.ShowMainPage(0);f.SetLoopView(false);f.ApplyAppearance();Application.DoEvents();using(Bitmap b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(0,0,b.Width,b.Height));b.Save(Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"../../Tracks-English-2.6.1.png")));}A(Language.T("● GRABANDO")=="● RECORDING","recording state translated");A(Language.T(MainForm.HelpText).Contains("QUICK START"),"help content translated");using(TrackDialog track=new TrackDialog(f.Engine,0,delegate{},delegate{},delegate{})){Language.Apply(track);A(Find(track,"Volume (0–200%)")!=null&&Find(track,"Record rhythm into track")!=null,"track dialog translated");}sp.KeyboardOptions.Reload();DataGridView grid=(DataGridView)F(sp.KeyboardOptions,"grid");Language.Apply(f);A(grid.Columns[1].HeaderText=="Action","keyboard editor headers translated");f.ShowOptions();sp.ShowThemes();Application.DoEvents();Language.Apply(f);using(Bitmap b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(0,0,b.Width,b.Height));b.Save(Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"../../Idioma-English-2.6.png")));}selector.SelectedIndex=0;A(Language.Code=="es"&&tabs.TabPages[0].Text=="PISTAS"&&Find(f,"AYUDA")!=null,"switching back restores Spanish");A(strips[0].DisplayName=="PISTA 01"&&((TextBox)F(f,"sessionName")).Text=="Nueva sesión","default names restore when returning to Spanish");A(Language.T("Pista 3")=="Pista 3","Spanish source strings remain unchanged");f.Engine.Dirty=false;f.Close();}Console.WriteLine("TOTAL "+n+" language checks passed");}catch(Exception e){Console.WriteLine("FAIL "+e);Environment.ExitCode=1;}finally{if(backup!=null)File.WriteAllBytes(pref,backup);else if(File.Exists(pref))File.Delete(pref);Language.Set("es");}}
}
